// Public bilingual technical notes; no device or preview operations.
const chinese = {"nb1 mascot": "nb1 项目形象", "Embedded Workbench / Model reference": "内嵌工作台 / 模型说明", "Open workbench ↗": "打开工作台 ↗", "MODEL REFERENCE": "模型说明", "One model, two fixed LED channels.": "一个模型，两个固定灯光通道。", "LED 1 is the blink(1) wordmark face; LED 2 is the ThingM face. Turning the view never swaps their identities.": "LED 1 对应 blink(1) 字样面，LED 2 对应 ThingM 字样面；转动视角不会交换灯号。", "Open 3D ↗": "打开 3D ↗", "View both faces ↗": "查看双面 ↗", "Display geometry": "显示模型", "The enclosure uses the attributed ThingM CAD. The derived assembly, supplemental USB connector and light field are visual approximations, not production CAD or calibrated optics.": "外壳采用已注明来源的 ThingM CAD。派生装配、补充 USB 插头与光场仅作视觉近似，不是生产 CAD 或校准光学模型。", "The original STL bytes and wordmarks are preserved. Geometry units are inferred from the device scale, not certified manufacturing dimensions.": "原始 STL 字节与字标保持不变。几何单位按设备比例推断，不是经过认证的制造尺寸。", "Preview and device state": "预览与设备状态", "Screen preview follows the canonical Sequence and Go playback plan. It does not submit a Job or control the light.": "屏幕预览遵循规范化 Sequence 与 Go 播放计划，不提交 Job，也不控制实体灯。", "Cached RGB readback and its timestamp are labeled separately. A screen image or cached value does not establish physical light output. Explicit Play uses the local daemon API.": "缓存 RGB 读回及时间分别标注。屏幕图像或缓存值不证明实际发光；明确点击播放才调用本机 daemon API。", "The two-face fallback remains available while loading, without WebGL, or after graphics context loss.": "加载中、不支持 WebGL 或图形上下文丢失时，仍可使用双面备用视图。", "Public technical sources": "公开技术来源", "CAD sources and modifications": "CAD 来源与修改", "Derived assembly measurements": "派生装配尺寸", "Manufacturer references describe the top and bottom LED numbering. Wordmark correspondence is a project mapping for the MK2; it is not a manufacturer quotation or qualification of another model.": "厂商资料说明上下 LED 编号。字标对应关系是项目的 MK2 通道映射，不是厂商原话，也不代表其他机型已验收。", "Licenses": "许可", "ThingM CAD and the derived display assembly retain CC-BY-SA-4.0 attribution. Three.js retains MIT notices. The approved project artwork is not an official ThingM or Nintendo character.": "ThingM CAD 与派生显示装配保留 CC-BY-SA-4.0 署名，Three.js 保留 MIT 声明。项目形象不是 ThingM 或任天堂官方角色。", "ThingM CAD license": "ThingM CAD 许可", "Three.js license": "Three.js 许可", "nb1 · Embedded Workbench": "nb1 · 内嵌工作台", "The illustration is not an optical measurement.": "示意图不是光学测量。"};
const entries = [];
const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
while (walker.nextNode()) { const node = walker.currentNode; if (chinese[node.textContent]) entries.push([node, node.textContent]); }
const images = [...document.images].map(node => [node, node.alt]);
const button = document.getElementById('model-language');
button.addEventListener('click', () => {
  const zh = document.documentElement.lang !== 'zh-CN';
  document.documentElement.lang = zh ? 'zh-CN' : 'en';
  for (const [node, english] of entries) node.textContent = zh ? chinese[english] : english;
  for (const [node, english] of images) node.alt = zh ? chinese[english] || english : english;
  button.textContent = zh ? 'English' : '中文';
  button.setAttribute('aria-label', zh ? 'Switch to English' : 'Switch to Chinese');
});
